/*
 * @file  init_clock.c
 * @brief Mikroe clock initialization for Nordic Semiconductor NRF51 MCUs.
 *        Generated by scripts/nordic_mcus.py - do not edit, change the generator instead.
 *
 * SystemInit:
 *   1. Nordic MDK SystemInit (system_nrf51.c, unmodified): errata workarounds and trims.
 *   2. Clock setup from the NECTO clock configuration (VALUE_* macros in core_header.h),
 *      in this order:
 *        a) XTALFREQ written before the HFXO starts (16 or 32 MHz crystal)
 *        b) HFXO started when CLOCK_TASKS_HFCLKSTART is set (HFCLK keeps running from HFINT otherwise)
 *        c) LFCLKSRC written and LFCLK started when CLOCK_TASKS_LFCLKSTART is set (after HFXO: LFCLK synth needs HFCLK)
 */

#include "core_header.h"
#include "mcu.h"

/* The MDK SystemInit is compiled here under another name and called from the MikroE SystemInit below. */
#define SystemInit nordic_mdk_system_init
#include "system_nrf51.c"
#undef SystemInit

void SystemInit( void )
{
    nordic_mdk_system_init();

    /* Tell the HFXO which crystal is fitted (must be set before it starts). */
    NRF_CLOCK->XTALFREQ = VALUE_CLOCK_XTALFREQ;

    if ( VALUE_CLOCK_TASKS_HFCLKSTART & 1 ) {
        /* Start the high frequency crystal oscillator and wait until it runs. */
        NRF_CLOCK->EVENTS_HFCLKSTARTED = 0;
        NRF_CLOCK->TASKS_HFCLKSTART = 1;
        while ( 0 == NRF_CLOCK->EVENTS_HFCLKSTARTED );
        NRF_CLOCK->EVENTS_HFCLKSTARTED = 0;
    }

    /* Select the LFCLK source, start LFCLK and wait until it runs. */
    if ( VALUE_CLOCK_TASKS_LFCLKSTART & 1 ) {
        NRF_CLOCK->LFCLKSRC = VALUE_CLOCK_LFCLKSRC;
        NRF_CLOCK->EVENTS_LFCLKSTARTED = 0;
        NRF_CLOCK->TASKS_LFCLKSTART = 1;
        while ( 0 == NRF_CLOCK->EVENTS_LFCLKSTARTED );
        NRF_CLOCK->EVENTS_LFCLKSTARTED = 0;
    }
}
